/** Tests FIRST, all Java UNRUN. Actual original assets/Frame/pool/shared physical pass;
 * inherited pass harness explicitly CONSTRUCTS Core/Ports/slot vectors, never World authority.
 * Coordinates below are source-authored literal controls for Root to confirm, not observed runs. */
class TestSonicCdR31aFlowerPass {
 @Test void nativeRootAndAllDataProductsAreActualOriginalSource()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){
  assertEquals(0x206064,h.assets.view(CdR31aAssets.Asset.OBJECT_INDEX).unsignedLong((0x1F-1)*4));var a=h.objects.flowerAssets();assertSame(a,h.objects.flowerAssets());assertEquals(0x2336D8,a.mappingsAddress());
  assertEquals("48b7482f83af1300d834e07ec7326e670740d8c5f89f5c8a2253de123e46bb41",sha(a.flower().mappings()));assertEquals("74105bb36227383768d51cd9084560633d8315a9c940e23e80c707532a5353e9",sha(a.flower().animationTable()));
  assertEquals(8,a.flower().mappingFrames().size());assertEquals(4,a.flower().animations().size());assertEquals(67,CdR31aAssets.Asset.values().length);var m=CdObjectMappings.fromR31aAssets(h.assets,h.objects);assertInstanceOf(CdObjectDrawQueue.FrameMapping.class,m.resolve(0x2336D8,false,7));assertThrows(UnsupportedOperationException.class,()->m.resolve(0x2336D8,false,8));}}
 @Test void respawnFreeInitRetainsDirtyFractionsAndDoesNotAllocateChildren()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){
  var s=seed(h,32,0,1,100,100).moveByte(SUBTYPE2,77).moveWord(X_FRACTION,0xCAFE).moveWord(Y_FRACTION,0xBEEF);h.placement.pool().write(s);var before=h.placement.capture();var state=h.frame.state();var clock=h.frame.vIntClock();h.walk();
  var expected=s.moveByte(SPRITE_FLAGS,4).moveByte(PRIORITY,1).moveByte(Y_RADIUS,0).moveWord(TILE,0x6D7).moveLong(MAPPINGS,0x2336D8).moveByte(ROUTINE,2).moveByte(ANIMATION,0).moveByte(PREVIOUS_ANIMATION,0).moveByte(ANIMATION_FRAME,1).moveByte(ANIMATION_TIME,3).moveByte(MAP_FRAME,0).addWord(Y,2);
  assertEquals(expected,h.placement.pool().state(32));nonwrites(before,h,Set.of(32));assertSame(state,h.frame.state());assertEquals(clock,h.frame.vIntClock());h.finish();}}
 @Test void savedBitSixSkipsFloorAndPreservesTheActualLoadedBit()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){
  var s=seed(h,32,0,0,100,100).moveByte(SAVED_FLAGS_ID,254);h.placement.pool().write(s);h.placement.bsetSavedFlag(254,1,CdObjectPlacementRuntime.SavedBit.MEMBER_7);h.placement.bsetSavedFlag(254,1,CdObjectPlacementRuntime.SavedBit.LOADED);var before=h.placement.capture();h.walk();var z=h.placement.pool().state(32);assertEquals(4,z.routine());assertEquals(3,z.unsignedByte(ANIMATION));assertEquals(0xA6D7,z.word(TILE));assertEquals(0xC0,h.placement.savedFlag(254,1));assertEquals(100,z.centreY());nonwrites(before,h,Set.of(32));h.finish();}}
 @Test void loadedBitAloneDoesNotPretendTheSeedWasAlreadyPlanted()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){var s=seed(h,32,0,0,100,100).moveByte(SAVED_FLAGS_ID,200);h.placement.pool().write(s);h.placement.bsetSavedFlag(200,1,CdObjectPlacementRuntime.SavedBit.LOADED);h.walk();assertEquals(2,h.placement.pool().state(32).routine());assertEquals(128,h.placement.savedFlag(200,1));h.finish();}}
 @Test void rawSavedTailDoesNotClampOrFabricateAByte()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){var s=seed(h,32,0,0,100,100).moveByte(SAVED_FLAGS_ID,255);h.placement.pool().write(s);assertThrows(IndexOutOfBoundsException.class,h::walk);assertEquals(0,h.placement.pool().state(32).routine());assertEquals(0xA6D7,h.placement.pool().state(32).word(TILE));assertNull(field(h.pass,"flowerEffect"));}}
 @Test void growAndDoneUseTheirExactLiteralAnimationPrefixesWithoutFloor()throws Exception{
  try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,6,1,100,100);h.walk();var s=h.placement.pool().state(32);assertEquals(0x26D7,s.word(TILE));assertEquals(2,s.unsignedByte(ANIMATION));assertEquals(5,s.unsignedByte(MAP_FRAME));assertEquals(1,s.unsignedByte(ANIMATION_TIME));h.finish();}
  try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,8,1,100,100);h.walk();var s=h.placement.pool().state(32);assertEquals(4,s.routine());assertEquals(3,s.unsignedByte(ANIMATION));assertEquals(6,s.unsignedByte(MAP_FRAME));assertEquals(0x13,s.unsignedByte(ANIMATION_TIME));h.finish();}}
 @Test void unknownRoutineRetiresBeforeAnyNativeWrite()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,10,1,100,100);var before=h.placement.capture();var e=assertThrows(CdFlower.UnsupportedFlower.class,h::walk);assertEquals(CdFlower.UnsupportedBoundary.ROUTINE_DISPATCH,e.boundary());nonwrites(before,h,Set.of());assertNull(field(h.pass,"flowerEffect"));}}
 @Test void heldUnknownScriptDefersItsFirstMissingDirectoryRead()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){var s=seed(h,32,4,1,100,100).moveByte(ANIMATION,255).moveByte(PREVIOUS_ANIMATION,255).moveByte(ANIMATION_TIME,1);h.placement.pool().write(s);h.walk();h.finish();assertEquals(0,h.placement.pool().state(32).unsignedByte(ANIMATION_TIME));var e=assertThrows(CdFlower.UnsupportedFlower.class,h::walk);assertEquals(CdFlower.UnsupportedBoundary.ANIMATION_DIRECTORY_READ,e.boundary());assertEquals(255,h.placement.pool().state(32).unsignedByte(ANIMATION_TIME));}}
 @Test void selectedInvalidMappingRemainsADeferredReadAfterTheBodyPrefix()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){var s=seed(h,32,4,1,100,100).moveByte(MAP_FRAME,8).moveByte(ANIMATION_TIME,1);h.placement.pool().write(s);var old=h.cut.cpuSat();h.walk();assertEquals(0,h.placement.pool().state(32).unsignedByte(ANIMATION_TIME));assertThrows(UnsupportedOperationException.class,h::finish);assertSame(old,h.cut.cpuSat());}}
 @Test void cachedReceiverRefreshesFromActualCurrentTerrainBeforeTheVisit()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){// The inherited alternate is explicitly CONSTRUCTED; mature routine4 makes no floor read.
  var old=field(h.pass,"flower");seed(h,32,4,1,100,100);h.terrainDiverged=true;h.walk();assertNotSame(old,field(h.pass,"flower"));assertSame(h.divergedTerrain,field(h.pass,"flowerTerrain"));h.finish();}}
 @Test void originalAngleCallsPublishCompleteFramePairsAndCannotReenterOrEscape()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,2,1,100,100);var b=(CdFlower)field(h.pass,"flower");var port=(CdFlower.PrimaryAngleCommit)field(b,"angleCommit");var held=new java.util.concurrent.atomic.AtomicReference<CdFlower.PrimaryAngleCall>();set(b,"angleCommit",(CdFlower.PrimaryAngleCommit)c->{held.set(c);var state=h.frame.state();assertThrows(IllegalStateException.class,()->h.pass.runWalk(7));assertFalse(h.frame.closed());port.commit(c);assertSame(state,h.frame.state());assertThrows(IllegalStateException.class,()->port.commit(c));});h.walk();assertFalse(b.isCurrentCall(held.get()));assertThrows(IllegalStateException.class,()->port.commit(held.get()));h.finish();}}
 @Test void clonedPublicationAndNoopDrawCannotGrantReceipts()throws Exception{
  try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,6,1,100,100);var b=(CdFlower)field(h.pass,"flower");var o=(CdFlower.DispatchObserver)field(b,"observer");set(b,"observer",new CdFlower.DispatchObserver(){public void beforePublication(CdFlower.Publication c){o.beforePublication(new CdFlower.Publication(c.ordinal(),c.kind(),c.cut(),c.source(),c.output()));}public void afterPublication(CdFlower.Publication c){o.afterPublication(c);}public void beforeCall(Object c){o.beforeCall(c);}public void afterCall(Object c){o.afterCall(c);}});assertThrows(IllegalStateException.class,h::walk);}
  try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,4,1,100,100);var b=(CdFlower)field(h.pass,"flower");set(b,"sourceDraw",(CdFlower.SourceDraw)c->{});assertThrows(IllegalStateException.class,h::walk);assertNull(field(h.pass,"flowerEffect"));}}
 @Test void originalAngleErrorRetainsThePrezeroAndRetiresAllScopes()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,2,1,100,100);var b=(CdFlower)field(h.pass,"flower");var port=(CdFlower.PrimaryAngleCommit)field(b,"angleCommit");var original=new AssertionError("after native prezero");set(b,"angleCommit",(CdFlower.PrimaryAngleCommit)c->{port.commit(c);throw original;});assertSame(original,assertThrows(AssertionError.class,h::walk));assertEquals(0,h.frame.environment().movement().globals().primaryAngle());assertNull(field(h.pass,"flowerEffect"));}}
 @Test void landingCountPublishesItsExistingCoreByteBeforeTheMissingPositionOwner()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){
  var source=seed(h,32,2,0,96,1024);
  // Actual shared read-owner oracle, not a native-run floor oracle. The fixed vector's
  // landing precondition must be confirmed by Root; production must never fit it.
  var floor=com.openggf.game.soniccd.objects.CdObjectCollisionCheck.objGetFloorDist(com.openggf.game.soniccd.player.CdPlayerTerrain.fromStageTerrain(h.cut.currentTerrain()),source);assertTrue(floor.distance()<0,"Source vector must genuinely land");var before=h.placement.capture();var count=h.cut.core().level().flowerCount();h.walk();assertEquals(96,h.cut.core().flowerPositions().word(0x100));assertEquals(h.placement.pool().state(32).centreY(),h.cut.core().flowerPositions().word(0x102));assertEquals((count&0xFF00FF)|((((count>>>8)+1)&255)<<8),h.cut.core().level().flowerCount());assertEquals((source.centreY()+floor.distance())&65535,h.placement.pool().state(32).centreY());assertEquals(floor.primaryAngle(),h.frame.environment().movement().globals().primaryAngle());nonwrites(before,h,Set.of(32));}}
 @Test void fullPhysicalPoolDoesNotCreateAnUnprovenFlowerChildOrReward()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){for(int w=32;w<128;w++)h.placement.pool().write(seed(h,w,4,1,100,100).moveByte(ANIMATION_TIME,1));var bank=h.placement.capture().savedFlags();var score=h.cut.world();h.walk();for(int w=32;w<128;w++)assertEquals(0x1F,h.placement.pool().state(w).id());assertArrayEquals(bank.copy(),h.placement.capture().savedFlags().copy());assertEquals(score,h.cut.world());h.finish();}}
 @Test void matureDispatchLeavesFullCoreFrameEnvironmentArtClockAndAllBanksUnchanged()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){
  seed(h,32,4,0,100,100);var core=h.cut.core();var cut=h.cut;var state=h.frame.state();var env=h.frame.environment();var art=h.frame.artState();var display=h.frame.display();var clock=h.frame.vIntClock();var bank=h.placement.capture();h.walk();
  assertEquals(cut,h.cut);assertSame(core,h.cut.core());assertSame(state,h.frame.state());assertSame(env,h.frame.environment());assertEquals(art,h.frame.artState());assertEquals(display,h.frame.display());assertEquals(clock,h.frame.vIntClock());assertEquals(1984,h.cut.core().reserved().length());nonwrites(bank,h,Set.of(32));h.finish();}}
 @Test void originalSavedReadsRejectCloneForeignThreadRepeatAndExpiration()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){
  seed(h,32,0,0,100,100);var b=(CdFlower)field(h.pass,"flower");var port=(CdFlower.SavedPort)field(b,"savedPort");var held=new java.util.concurrent.atomic.AtomicReference<CdFlower.SavedCall>();
  set(b,"savedPort",(CdFlower.SavedPort)c->{held.set(c);assertEquals(CdFlower.SavedSite.TIME_ZONE,c.site());assertThrows(IllegalStateException.class,()->port.access(new CdFlower.SavedCall(c.ordinal(),c.site(),c.cut(),c.source(),c.offset(),c.value())));
   var failure=new java.util.concurrent.atomic.AtomicReference<Throwable>();var thread=new Thread(()->{try{port.access(c);}catch(Throwable x){failure.set(x);}});thread.start();try{thread.join(5000);}catch(InterruptedException x){throw new AssertionError(x);}assertFalse(thread.isAlive());assertInstanceOf(IllegalStateException.class,failure.get());
   int raw=port.access(c);assertEquals(h.frame.environment().movement().gates().timeZone(),raw);assertThrows(IllegalStateException.class,()->port.access(c));return raw;});h.walk();assertFalse(b.isCurrentCall(held.get()));assertThrows(IllegalStateException.class,()->port.access(held.get()));assertFalse(h.frame.closed());h.finish();}}
 @Test void caughtReceiverReentryDoesNotRetireTheHealthyOriginalScope()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){
  seed(h,32,4,1,100,100);var b=(CdFlower)field(h.pass,"flower");var port=(CdFlower.SourceDraw)field(b,"sourceDraw");set(b,"sourceDraw",(CdFlower.SourceDraw)c->{assertThrows(IllegalStateException.class,()->b.run(32));assertThrows(IllegalStateException.class,()->h.pass.runWalk(7));assertFalse(h.frame.closed());port.draw(c);});h.walk();assertFalse(h.frame.closed());h.finish();}}
 @Test void unownedSavedSlotAndFrameMutationsRetainOriginalFaultAndDistinctVerification()throws Exception{
  for(int mode=0;mode<3;mode++)try(var h=new TestSonicCdR31aObjectPass.Harness()){seed(h,32,6,1,100,100);var b=(CdFlower)field(h.pass,"flower");var original=(CdFlower.DispatchObserver)field(b,"observer");var error=new AssertionError("Flower original prefix "+mode);final int what=mode;
   set(b,"observer",new CdFlower.DispatchObserver(){public void beforePublication(CdFlower.Publication c){original.beforePublication(c);if(what==0)h.placement.bsetSavedFlag(200,2,CdObjectPlacementRuntime.SavedBit.LOADED);if(what==1)h.placement.pool().write(h.placement.pool().state(127).moveByte(RAMP_TIMER,77));if(what==2)h.frame.applyPreparedObjectSolidPublication(h.frame.prepareObjectPrimaryAngle(h.frame.environment().movement().globals().primaryAngle(),7));throw error;}public void afterPublication(CdFlower.Publication c){original.afterPublication(c);}public void beforeCall(Object c){original.beforeCall(c);}public void afterCall(Object c){original.afterCall(c);}});
   assertSame(error,assertThrows(AssertionError.class,h::walk));assertTrue(error.getSuppressed().length>0);for(var f:error.getSuppressed())assertNotSame(error,f);if(what==0)assertEquals(128,h.placement.savedFlag(200,2));if(what==1)assertEquals(77,h.placement.pool().state(127).unsignedByte(RAMP_TIMER));if(what==2)assertEquals(7,h.frame.environment().movement().globals().primaryAngle());assertNull(field(h.pass,"flowerEffect"));}}
 @Test void countByteWrapRetainsOtherPeriodsAndMasksOnlyThePositionIndex()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){
  var c=h.cut;var l=c.core().level();var dirty=new CdLevelGlobals(l.levelRestart(),l.updateHudTime(),l.checkpoint(),l.spawnMode(),l.plcLoadFlags(),0xA5FF3C,l.fadeEnableDisplay(),l.powerup(),l.timeOver());h.cut=new SonicCdR31aObjectPass.Cut(c.core().level(dirty),c.ring(),c.currentTerrain(),c.contact(),c.world(),c.noBumperByte(),c.cameraXWord(),c.cameraYWord(),c.scrollLockWord(),c.layerByte(),c.cpuSat(),c.completedCpu(),c.sounds(),c.amyCapturedByte());
  var source=seed(h,32,2,0,96,1024);var floor=CdObjectCollisionCheck.objGetFloorDist(com.openggf.game.soniccd.player.CdPlayerTerrain.fromStageTerrain(h.cut.currentTerrain()),source);assertTrue(floor.distance()<0);h.walk();assertEquals(96,h.cut.core().flowerPositions().word(0x1FC));assertEquals(h.placement.pool().state(32).centreY(),h.cut.core().flowerPositions().word(0x1FE));assertEquals(0xA5003C,h.cut.core().level().flowerCount());}}
 @Test void countOwnerRuntimeAndErrorFaultsKeepOnlyTheirReachedNativePrefix()throws Exception{
  for(boolean after:new boolean[]{false,true})try(var h=new TestSonicCdR31aObjectPass.Harness()){var source=seed(h,32,2,0,96,1024);var floor=CdObjectCollisionCheck.objGetFloorDist(com.openggf.game.soniccd.player.CdPlayerTerrain.fromStageTerrain(h.cut.currentTerrain()),source);assertTrue(floor.distance()<0);var old=h.cut.core().level().flowerCount();var bank=h.placement.capture();Throwable original=after?new AssertionError("after real count owner"):new IllegalStateException("before real count owner");
   h.beforeAdopt=()->{if(h.lastAdoption.next().core().level().flowerCount()!=old){if(after)h.afterAdopt=()->{throw (Error)original;};else throw (RuntimeException)original;}};
   Throwable seen=after?assertThrows(Error.class,h::walk):assertThrows(RuntimeException.class,h::walk);assertSame(original,seen);assertEquals(after?0x100:old,h.cut.core().level().flowerCount());assertEquals((source.centreY()+floor.distance())&65535,h.placement.pool().state(32).centreY());assertEquals(2,h.placement.pool().state(32).routine());nonwrites(bank,h,Set.of(32));assertNull(field(h.pass,"flowerEffect"));}}
 @Test void labelledPureCountProjectionKeepsItsNativeFadeAliasWithoutMintingAWorldCall(){
  // Constructed DTOs test projection arithmetic only; they are never executable receipts.
  var l=new CdLevelGlobals(0x1234,0x56,0x78,0x9A,0xBC,0xA5FF3C,255,0xDE,0xF0);
  var c=new CdFlower.SavedCall(1,CdFlower.SavedSite.COUNT_INCREMENT,null,null,3,0);var next=SonicCdR31aObjectPass.flowerCountLevel(l,c);
  assertEquals(0xA5FF3C,next.flowerCount());assertEquals(0,next.fadeEnableDisplay());assertEquals(l.powerup(),next.powerup());assertEquals(l.timeOver(),next.timeOver());
  assertThrows(IllegalArgumentException.class,()->SonicCdR31aObjectPass.flowerCountLevel(l,new CdFlower.SavedCall(1,CdFlower.SavedSite.COUNT_INCREMENT,null,null,4,0)));}
 @Test void respawnFreeLandingUsesTheActualFloorWithoutCountOrPositionStorage()throws Exception{try(var h=new TestSonicCdR31aObjectPass.Harness()){
  var source=seed(h,32,2,1,96,1024);var floor=CdObjectCollisionCheck.objGetFloorDist(com.openggf.game.soniccd.player.CdPlayerTerrain.fromStageTerrain(h.cut.currentTerrain()),source);assertTrue(floor.distance()<0,"Original-media landing precondition");var before=h.placement.capture();var core=h.cut.core();h.walk();var out=h.placement.pool().state(32);assertEquals(4,out.routine());assertEquals(1,out.unsignedByte(ANIMATION));assertEquals(0x30,out.unsignedByte(Y_RADIUS));assertEquals(2,out.unsignedByte(MAP_FRAME));assertEquals(3,out.unsignedByte(ANIMATION_TIME));assertEquals((source.centreY()+floor.distance())&65535,out.centreY());assertEquals(floor.primaryAngle(),h.frame.environment().movement().globals().primaryAngle());assertSame(core,h.cut.core());nonwrites(before,h,Set.of(32));h.finish();}}
 static CdObjectState seed(TestSonicCdR31aObjectPass.Harness h,int whole,int routine,int subtype,int x,int y){var s=h.placement.pool().state(whole).moveByte(ID,0x1F).moveByte(ROUTINE,routine).moveByte(SUBTYPE,subtype).moveByte(SPRITE_FLAGS,4).moveWord(X,x).moveWord(Y,y).moveLong(MAPPINGS,0x2336D8);h.placement.pool().write(s);return s;}
 private static void nonwrites(CdObjectPlacementRuntime.Snapshot b,TestSonicCdR31aObjectPass.Harness h,Set<Integer> changed){var n=h.placement.capture();assertEquals(b.status(),n.status());assertArrayEquals(b.savedFlags().copy(),n.savedFlags().copy());for(int w=32;w<128;w++)if(!changed.contains(w))assertEquals(b.pool().slots().get(w-32),h.placement.pool().state(w));}
 private static Object field(Object o,String n)throws Exception{var f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private static void set(Object o,String n,Object v)throws Exception{var f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}
 private static String sha(CdAssetBytes b){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(b.copy()));}catch(Exception e){throw new AssertionError(e);}}
}
